contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint minSum, uint amt) public {
        require(minSum > 0);
        c.SetMinSum(minSum);
        c.Deposit{value: amt}();
        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;
        bool reverted;
        try c.Collect(amt) { reverted = false; } catch { reverted = true; }
        assert(!reverted
            && c.balances(address(this)) == balBefore
            && address(c).balance == contractBalBefore
            && address(this).balance == myBalBefore);
    }
}

